'use strict';
const $=id=>document.getElementById(id);
const ROUTE=(location.pathname.split('/')[1]||'menu');
const nav=[['menu','منوی مشتری','☕'],['staff','پنل کارکنان','♧'],['cashier','صندوق','▣'],['admin','منو و میزها','▦'],['inventory','انبار و رسپی','◈'],['finance','حسابداری','◉'],['analytics','داشبورد و تحلیل','▥'],['crm','باشگاه مشتریان','♡'],['attendance','حضور و غیاب','◷'],['presentation','سناریوی ارائه','✧']];
const titles=Object.fromEntries(nav.map(x=>[x[0],x[1]]));
const statusText={new:'جدید',accepted:'تأیید شده',preparing:'در حال آماده‌سازی',ready:'آماده تحویل',completed:'تحویل‌شده',cancelled:'لغو شده'};
const nextStatus={new:['accepted','cancelled'],accepted:['preparing','cancelled'],preparing:['ready'],ready:['completed'],completed:[],cancelled:[]};
const actionLabel={accepted:'پذیرش سفارش',preparing:'شروع آماده‌سازی',ready:'اعلام آماده',completed:'تحویل به مشتری',cancelled:'لغو سفارش'};
const format=n=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:6}).format(Number(n)||0);
const money=n=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2}).format(Number(n)||0)+' تومان';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>s?new Date(s).toLocaleString('fa-IR',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tehran'}):'—';
const getTable=()=>Number(new URLSearchParams(location.search).get('table'))||null;
const idKey=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);
const model={user:null, menu:{categories:[],products:[],tables:[]},cart:[],category:'all',editingProduct:null,selectedRecipe:null,pendingKey:idKey(),order:null};
let toastTimer=null;
function toast(text,error=false){const t=$('toast');t.textContent=text;t.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='toast',3600)}
async function api(path,options={}){const res=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data;try{data=await res.json()}catch{data={detail:'پاسخ سرور خوانده نشد'}}if(!res.ok){const error=Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));error.status=res.status;throw error}return data}
function post(path,body,method='POST'){return api(path,{method,body:JSON.stringify(body)})}
async function loadUser(){try{model.user=await api('/auth/me')}catch{model.user=null}}
function mark(text,kind=''){return `<span class="tag ${kind}">${esc(text)}</span>`}
function stat(title,val,hint,icon='◈',positive=false){return `<div class="stat ${positive?'positive':''}"><div class="row between"><small>${esc(title)}</small><span class="stat-icon">${icon}</span></div><div class="metric">${esc(val)}</div><small>${esc(hint)}</small></div>`}
function empty(text,subtitle=''){return `<div class="empty"><div><strong>${esc(text)}</strong><span>${esc(subtitle)}</span></div></div>`}
function heading(title,sub,extra=''){return `<div class="page-head"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>${extra}</div>`}
function logo(){return `<a href="/menu" class="logo"><span class="brand-mark">N</span><span class="brand-name">کافه یار ۳۶۰<small>کافه نیما · Cafe Yar 360</small></span></a>`}
function actionsFor(role){if(role==='staff')return ['menu','staff','attendance','presentation'];if(role==='cashier')return ['menu','cashier','attendance','presentation'];return ['menu','staff','cashier','admin','inventory','finance','analytics','crm','attendance','presentation']}
function shell(content){const accessible=actionsFor(model.user?.role);const links=nav.filter(n=>accessible.includes(n[0]));return `<div class="office"><aside class="sidebar">${logo()}<div><div class="nav-group-title">فضای مدیریت</div><nav class="side-nav">${links.map(([path,label,ico])=>`<a class="${ROUTE===path?'active':''}" href="/${path}"><span class="nav-symbol">${ico}</span>${esc(label)}</a>`).join('')}</nav></div><div class="sidebar-bottom">✦ نسخه نمایشی یکپارچه<br>امکانات آنلاین پرداخت عمداً غیرفعال است.<br><span style="color:#a0b4a7">داده‌ها و قیمت‌ها آزمایشی هستند.</span></div></aside><main class="office-main"><header class="topbar"><div><div class="breadcrumbs">کافه یار ۳۶۰ / فضای مدیریت / ${esc(titles[ROUTE]||'')}</div><h1>${esc(titles[ROUTE]||'داشبورد')}</h1></div><div class="row"><span class="pill-date">نسخه دمو · قابل اجرا روی شبکه محلی</span><span class="avatar">${esc((model.user?.name||'ن')[0])}</span>${model.user?`<button class="btn btn-light btn-sm" data-action="logout">خروج</button>`:`<button class="btn btn-primary btn-sm" data-action="login">ورود</button>`}</div></header>${content}</main><nav class="mobile-nav">${links.filter(n=>['menu','staff','cashier','analytics','presentation'].includes(n[0])).map(([p,l,i])=>`<a href="/${p}" class="${ROUTE===p?'active':''}"><span>${i}</span>${esc(l)}</a>`).join('')}</nav></div>`}
function requiresAuth(){return !['menu','presentation'].includes(ROUTE)}
async function boot(){try{if(!model.config){model.config=await api('/public/config');document.querySelector('.demo-creds').hidden=!model.config.demo}await loadUser();if(ROUTE==='menu')return await customer();if(ROUTE==='presentation')return presentation();if(!model.user){$('app').innerHTML=shell(`<div class="panel">${empty('برای دیدن این بخش وارد شوید','با حسابی که مدیر سیستم تعریف کرده است وارد شوید.')}<div class="row" style="justify-content:center"><button class="btn btn-primary" data-action="login">ورود به پنل</button></div></div>`);openLogin();return}if(model.user.role==='staff'&&!['staff','attendance'].includes(ROUTE)||model.user.role==='cashier'&&!['cashier','attendance'].includes(ROUTE)){ $('app').innerHTML=shell(`<div class="panel">${empty('به این بخش دسترسی ندارید','برای این بخش باید با حساب مدیر وارد شوید.')}</div>`);return}const pages={staff,cashier,admin,inventory,finance,analytics,crm,attendance};await pages[ROUTE]?.()}catch(e){$('app').innerHTML=`<div class="customer-shell">${logo()}<div class="panel" style="margin:70px 0">${empty('دریافت اطلاعات با خطا مواجه شد',e.message)}<button class="btn btn-primary" onclick="location.reload()">تلاش دوباره</button></div></div>`;toast(e.message,true)}}
function openLogin(){$('login-dialog').showModal()}
function closeLogin(){$('login-dialog').close()}
const DEMO_USERS={admin:'admin',cashier:'cashier',barista:'barista'};
$('login-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post('/auth/login',{username:f.get('username'),password:f.get('password')});closeLogin();toast('ورود موفق بود');await boot()}catch(err){toast(err.message,true)}});
document.querySelector('.close-dialog').onclick=closeLogin;
document.querySelectorAll('[data-login]').forEach(b=>b.onclick=()=>{$('login-form').querySelector('[name=username]').value=DEMO_USERS[b.dataset.login];$('login-form').querySelector('[name=password]').value='';$('login-form').querySelector('[name=password]').focus();});

function customerHeader(){const table=getTable(),label=model.menu.tables.includes(table)?`میز شماره ${format(table)}`:'سفارش بیرون‌بر';return `<div class="customer-shell"><header class="customer-nav">${logo()}<nav class="nav-links"><a href="#menu-list">منوی امروز</a><a href="/presentation">معرفی سامانه</a><a href="/staff" class="btn btn-outline btn-sm">ورود کارکنان ↗</a></nav></header><div class="customer-hero"><div class="hero-content"><p class="eyebrow">FRESHLY MADE • EVERYDAY</p><h1>لحظه خوب،<br>با یک فنجان شروع می‌شود.</h1><p>منوی امروز را ببینید، نوشیدنی دلخواهتان را انتخاب کنید و تا آماده‌شدن سفارش همراه ما باشید.</p><div class="row wrap" style="margin-top:20px">${mark(label,'dark')}${mark('سفارش بدون نصب اپلیکیشن','dark')}</div></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><div class="hero-orbit"></div><div class="cup"></div><div class="art-badge">هر فنجان، یک تجربه ☕</div></div></div><div class="feature-strip"><span><b class="feature-dot">✓</b> ثبت آسان با QR میز</span><span><b class="feature-dot">✓</b> تهیه تازه پس از سفارش</span><span><b class="feature-dot">✓</b> پرداخت نقدی و کارتخوان</span><span><b class="feature-dot">✓</b> پیگیری وضعیت در لحظه</span></div>`}
async function customer(){model.menu=await api('/public/menu');const cats=model.menu.categories;const filtered=model.menu.products.filter(p=>model.category==='all'||String(p.category_id)===model.category);let orderStored=null;try{orderStored=sessionStorage.getItem('cafe-nima-order')}catch{}if(orderStored&&!model.order){try{model.order=JSON.parse(orderStored)}catch{}}$('app').innerHTML=customerHeader()+`<section id="menu-list"><div class="section-heading"><div><p class="eyebrow">OUR MENU</p><h2>چی میل دارید؟</h2><p class="dim">یک انتخاب خوشمزه، فقط چند لمس فاصله دارد.</p></div><span>${mark(format(model.menu.products.length)+' آیتم تازه')}</span></div><nav class="tabs" aria-label="دسته‌بندی منو"><button data-action="category" data-id="all" class="${model.category==='all'?'active':''}">همه محصولات</button>${cats.map(x=>`<button data-action="category" data-id="${x.id}" class="${model.category===String(x.id)?'active':''}">${esc(x.name)}</button>`).join('')}</nav><div class="product-grid">${filtered.map(p=>`<article class="product-card"><div class="product-image"><span class="emoji">${esc(p.emoji)}</span><small>${esc(cats.find(c=>c.id===p.category_id)?.name||'')}</small></div><div class="product-info"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="product-bottom"><span class="money">${money(p.price)}</span><button class="plus-btn" data-action="add" data-id="${p.id}" aria-label="افزودن ${esc(p.name)} به سبد">+</button></div></div></article>`).join('')}</div></section><section id="order-result">${orderStatusHtml()}</section><footer class="customer-footer"><span>© کافه یار ۳۶۰ | تهیه‌شده با عشق و قهوه</span><span>نسخه آزمایشی سیستم یکپارچه · پرداخت آنلاین غیرفعال</span></footer></div><div class="cart-floating" id="cart-floating"><div><strong id="floating-count">سبد سفارش</strong><div style="font-size:11px;color:#b9c9be" id="floating-price">۰ تومان</div></div><button data-action="open-cart" class="btn">مشاهده سفارش <span>↗</span></button></div><div class="cart-pane" id="cart-pane"><aside class="cart-drawer"><div class="row between"><div><p class="eyebrow">YOUR ORDER</p><h2>سفارش شما</h2></div><button class="icon-btn" data-action="close-cart" aria-label="بستن">×</button></div><div id="cart-content"></div></aside></div>`;syncCart();if(model.order)pollStatus()}
function orderStatusHtml(){if(!model.order)return '';let o=model.order;const status=o.latest?.status||o.status;const steps=['new','accepted','preparing','ready','completed'];const pos=steps.indexOf(status);return `<div class="success-box" style="margin-top:34px"><div class="row between wrap"><div><p class="eyebrow">ORDER TRACKING</p><h2>سفارش شما ثبت شده است ✓</h2><div class="dim">کد سفارش: <strong>${esc(o.code)}</strong> | مبلغ ${money(o.total)}</div></div>${mark(statusText[status]||status,status==='ready'?'':'dark')}</div><div class="order-flow">${steps.map((s,i)=>`<span class="${i<=pos?'done':''}">${statusText[s]}</span>`).join('')}</div><p class="dim" style="font-size:12px;margin:0">وضعیت سفارش به‌صورت خودکار به‌روزرسانی می‌شود. ${o.latest?.payment_id?'تسویه در صندوق ثبت شده است.':'پرداخت پس از ثبت در صندوق تأیید خواهد شد.'}</p></div>`}
async function pollStatus(){if(!model.order)return;try{model.order.latest=await api(`/orders/${encodeURIComponent(model.order.code)}/status?token=${encodeURIComponent(model.order.token)}`);const x=$('order-result');if(x)x.innerHTML=orderStatusHtml()}catch(err){if(err.message!=='Failed to fetch')console.warn('Status polling:',err.message)}}
setInterval(()=>{if(ROUTE==='menu'&&model.order)pollStatus()},7500);
function cartItemByKey(key){return model.cart.find(x=>x.key===key)}
function cartTotal(){return model.cart.reduce((sum,i)=>{const p=model.menu.products.find(p=>p.id===i.product_id),a=p?.addons?.find(a=>a.id===i.addon_id);return sum+(p?.price||0)*i.qty+(a?.price||0)*i.qty},0)}
function syncCart(){const count=model.cart.reduce((n,i)=>n+i.qty,0);if($('floating-count'))$('floating-count').textContent='سبد سفارش · '+format(count)+' مورد';if($('floating-price'))$('floating-price').textContent=money(cartTotal());if(!$('cart-content'))return;let table=getTable();if(!model.menu.tables.includes(table))table=null;$('cart-content').innerHTML=`${model.cart.length?model.cart.map((i,j)=>{let p=model.menu.products.find(p=>p.id===i.product_id);return `<div class="cart-item"><div><h3>${esc(p.name)}</h3><span class="dim" style="font-size:11px">${money(p.price)}</span>${p.addons?.length?`<select data-action="addon" data-index="${j}" style="margin:9px 0 0;min-height:36px;font-size:11px"><option value="">بدون افزودنی</option>${p.addons.map(a=>`<option value="${a.id}" ${i.addon_id===a.id?'selected':''}>${esc(a.name)} + ${money(a.price)}</option>`).join('')}</select>`:''}</div><div style="text-align:left"><div class="count-control"><button data-action="qty" data-index="${j}" data-delta="-1">−</button><b>${format(i.qty)}</b><button data-action="qty" data-index="${j}" data-delta="1">+</button></div></div></div>`}).join(''):empty('هنوز چیزی انتخاب نکرده‌اید','اول از منوی کافه یک محصول خوشمزه انتخاب کنید.')}
  <form data-form="order" class="stack" style="margin-top:18px"><div class="row between"><strong>مبلغ سفارش</strong><strong class="money cart-total">${money(cartTotal())}</strong></div><hr class="sep" style="width:100%;margin:4px 0"><div class="field-grid"><label>نام مشتری (اختیاری)<input name="name" maxlength="80" placeholder="نام شما"></label><label>موبایل (اختیاری)<input name="phone" inputmode="tel" dir="ltr" maxlength="15" placeholder="09123456789"></label></div><label>یادداشت سفارش<textarea name="note" rows="2" maxlength="500" placeholder="مثلاً بدون شکر یا کم‌یخ"></textarea></label><label>حساسیت غذایی (در صورت وجود)<input name="allergy" maxlength="300" placeholder="مثلاً حساسیت به لبنیات"></label><label class="row" style="align-items:flex-start;font-weight:400"><input type="checkbox" name="consent" style="margin-top:4px"><span>با ثبت شماره تلفن من در باشگاه مشتریان و استفاده برای سوابق خرید موافقم.</span></label><div><label>شیوه دریافت</label><div class="radio-line"><label><input name="fulfillment" type="radio" value="table" ${table?'checked':'disabled'}> میز ${table?format(table):'(QR لازم است)'}</label><label><input name="fulfillment" type="radio" value="takeaway" ${table?'':'checked'}> بیرون‌بر</label></div></div><div><label>روش پرداخت</label><div class="radio-line"><label><input name="payment" type="radio" value="pos" checked> کارتخوان</label><label><input name="payment" type="radio" value="cash"> نقدی</label><label class="disabled"><input type="radio" disabled> آنلاین (به‌زودی)</label></div></div><button class="btn btn-primary full" type="submit" ${model.cart.length?'':'disabled'}>ثبت نهایی سفارش ${money(cartTotal())} ↖</button><small class="muted">اطلاعات به سرور محلی ارسال و در پنل کارکنان ثبت می‌شود. درگاه اینترنتی فعال نیست.</small></form>`}

function orderCard(o,role){const paid=!!o.payment;const actions=role==='staff'?(nextStatus[o.status]||[]).map(s=>`<button class="btn ${s==='cancelled'?'btn-light':s==='completed'?'btn-accent':'btn-primary'} btn-sm" data-action="status" data-id="${o.id}" data-status="${s}">${actionLabel[s]}</button>`).join(''):(!paid&&o.status!=='cancelled'?`<button class="btn btn-primary btn-sm" data-action="pay" data-id="${o.id}" data-method="${o.payment_method}">ثبت تسویه ${money(o.total)}</button>`:'');const allergens=o.allergy_note?`<div class="note allergy">⚠ حساسیت غذایی: ${esc(o.allergy_note)}</div>`:'';return `<article class="order-card"><div class="row between"><div><h3>${esc(o.code)}</h3><div class="dim" style="font-size:10px">${fmtDate(o.created_at)}</div></div>${mark(statusText[o.status]||o.status,o.status==='cancelled'?'danger':o.status==='ready'?'':'dark')}</div><div class="row between"><span class="tag">${o.table_num?'میز '+format(o.table_num):'بیرون‌بر'}</span><span class="money">${money(o.total)}</span></div><div class="order-items">${o.items.map(i=>`${format(i.qty)} × ${esc(i.name)} ${i.addon_name?`(${esc(i.addon_name)})`:''}`).join(' • ')}</div>${o.note?`<div class="note">توضیحات: ${esc(o.note)}</div>`:''}${allergens}<div class="order-footer"><span>${mark(paymentLabel(o.payment_status|| (paid?'paid':'unpaid')),paid?'':'warning')}</span><div class="row wrap gap-sm">${actions||'<span class="dim" style="font-size:11px">اقدام دیگری لازم نیست</span>'}</div></div></article>`}
async function staff(){const [activeOrders,history]=await Promise.all([api('/orders?queue=active'),api('/orders')]);const orders=[...activeOrders,...history.filter(o=>['completed','cancelled'].includes(o.status))];const active=orders.filter(o=>!['completed','cancelled'].includes(o.status)),done=orders.filter(o=>o.status==='completed').length;$('app').innerHTML=shell(`${heading('ایستگاه آماده‌سازی','همه سفارش‌ها از منوی مشتری به این صفحه می‌رسند.',`<button class="btn btn-outline btn-sm" data-action="refresh">↻ به‌روزرسانی</button>`)}<div class="grid cols-4 mb">${stat('در صف پذیرش',format(active.filter(x=>x.status==='new').length),'سفارش‌های جدید','♧')}${stat('در حال آماده‌سازی',format(active.filter(x=>['accepted','preparing'].includes(x.status)).length),'در صف باریستا','♨')}${stat('آماده تحویل',format(active.filter(x=>x.status==='ready').length),'منتظر تحویل','✓',true)}${stat('تحویل‌شده',format(done),'از ۱۰۰ سفارش اخیر','▣')}</div><section class="panel"><div class="panel-head"><h3>صف سفارش‌های فعال</h3>${mark(format(active.length)+' سفارش')}</div><div class="grid cols-3">${active.length?active.map(o=>orderCard(o,'staff')).join(''):empty('سفارشی در صف نیست')}</div></section><p class="notice mt">برای سفارش دارای حساسیت غذایی، ثبت پذیرش فقط پس از تأیید مشاهده هشدار ممکن است. پایان سفارش، موجودی مواد اولیه را به‌صورت خودکار کاهش می‌دهد.</p>`)}
async function cashier(){
 const [history,open,totals,issues,shifts,requests,exceptions]=await Promise.all([
  api(`/cashier/payments?limit=20&offset=${model.cashOffset||0}&payment_status=${model.cashFilter||'all'}`),api('/orders?queue=unpaid'),api('/cashier/summary'),api('/cashier/discrepancies'),api('/cashier/shifts'),api('/cashier/requests'),model.user.role==='admin'?api('/cashier/exceptions'):Promise.resolve([])
 ]);
 model.cashShift=shifts.active;
 $('app').innerHTML=shell(`${heading('مدیریت پرداخت‌ها','کافه نیما · تسویه دستی نقدی و کارتخوان؛ ثبت عملیات در شیفت یا با هماهنگی مدیر.',`<button class="btn btn-outline btn-sm" data-action="refresh">↻ به‌روزرسانی</button>`)}
 <div class="grid cols-4 mb">${stat('در انتظار تسویه',format(open.length),'بدون دریافت وجه','▣')}${stat('دریافتی امروز',money(totals.received_today),'همه دریافت‌های روز تهران','◉',true)}${stat('استرداد امروز',money(totals.refunded_today),'خروج وجه ثبت‌شده','↩')}${stat('خالص دریافتی امروز',money(totals.net_received_today),'دریافت منهای استرداد','✓')}</div>
 ${shiftPanel(shifts)}
 <section class="panel mt"><div class="panel-head"><h3>سفارش‌های تسویه‌نشده</h3>${mark(format(open.length)+' سفارش','warning')}</div><div class="grid cols-3">${open.length?open.map(o=>orderCard(o,'cashier')).join(''):empty('سفارش تسویه‌نشده ندارید')}</div></section>
 <section class="panel mt"><div class="panel-head"><h3>تراکنش‌های ثبت‌شده</h3><span class="panel-sub">${format(history.total)} پرداخت · تاریخچه کامل صفحه‌بندی‌شده</span></div>
 <form data-form="cashier-filter" class="row wrap mb"><label>وضعیت مالی<select name="payment_status">${[['all','همه'],['paid','تسویه‌شده'],['partially_refunded','استرداد جزئی'],['refunded','استرداد کامل']].map(([key,label])=>`<option value="${key}" ${model.cashFilter===key?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn btn-outline">اعمال وضعیت</button></form>
 <div class="table-wrap"><table class="data-table"><thead><tr><th>سفارش</th><th>وضعیت سفارش / مالی</th><th>پرداخت</th><th>استرداد</th><th>زمان</th><th>عملیات</th></tr></thead><tbody>${history.items.map(o=>`<tr><td>${esc(o.code)}</td><td>${esc(statusText[o.status])}<br>${esc(paymentLabel(o.payment_status))}</td><td>${o.payment.method==='pos'?'کارتخوان':'نقدی'}<br>${money(o.payment.amount)}</td><td>${money(o.refunded_minor/100)}</td><td>${fmtDate(o.payment.created_at)}</td><td><a class="btn btn-outline btn-sm" href="/receipts/${o.id}" target="_blank" rel="noopener">رسید</a> <button class="btn btn-light btn-sm" data-action="payment-discrepancy" data-pid="${o.payment.id}">مغایرت</button> <button class="btn btn-light btn-sm" data-action="payment-correction" data-oid="${o.id}">${model.user.role==='admin'?'اصلاح روش':'درخواست اصلاح'}</button>${o.payment_status!=='refunded'?` <button class="btn btn-light btn-sm" data-action="refund-payment" data-oid="${o.id}">${model.user.role==='admin'?'استرداد':'درخواست استرداد'}</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">پرداختی با این وضعیت نیست.</td></tr>'}</tbody></table></div>
 <div class="row wrap mt"><button class="btn btn-outline" data-action="cash-page" data-offset="${Math.max(0,(model.cashOffset||0)-20)}" ${(model.cashOffset||0)===0?'disabled':''}>قبلی</button><span>${format((model.cashOffset||0)+1)} تا ${format(Math.min((model.cashOffset||0)+20,history.total))} از ${format(history.total)}</span><button class="btn btn-outline" data-action="cash-page" data-offset="${(model.cashOffset||0)+20}" ${(model.cashOffset||0)+20>=history.total?'disabled':''}>بعدی</button></div></section>
 ${requestPanel(requests)}${exceptionPanel(exceptions)}${discrepancyPanel(issues)}`);
}
function paymentLabel(status){return ({unpaid:'تسویه‌نشده',paid:'تسویه‌شده',partially_refunded:'استرداد جزئی',refunded:'استرداد کامل'})[status]||status}
function shiftPanel(data){const s=data.active;return `<section class="panel"><h3>شیفت صندوق مشترک</h3>${s?`${summaryRows([['شماره شیفت',format(s.id)],['مسئول شیفت',s.opened_by_name],['موجودی افتتاحیه',money(s.opening_minor/100)],['وجه نقد مورد انتظار',money(s.expected_minor/100)],['گردش خالص کارتخوان',money(s.pos_net_minor/100)]])}${model.user.role==='admin'||model.user.id===s.opened_by?`<form data-form="close-shift" data-id="${s.id}" class="stack mt"><label>شمارش واقعی نقد صندوق (تومان)<input name="counted_amount" type="number" min="0" step="0.01" required></label><label>توضیح شمارش / اختلاف<input name="note" maxlength="500"></label><button class="btn btn-primary">بستن شیفت</button></form>`:'<p>مسئول شیفت یا مدیر می‌تواند شیفت را ببندد.</p>'}`:`<p class="notice">شیفت باز نیست. برای ثبت عملیات، شیفت باز کنید یا هماهنگی مدیر را ثبت کنید.</p><form data-form="open-shift" class="row wrap mt"><label>وجه نقد شمارش‌شده افتتاحیه (تومان)<input name="opening_amount" type="number" min="0" step="0.01" required value="0"></label><button class="btn btn-primary">باز کردن شیفت</button></form>`}
 <details class="mt"><summary>شیفت‌های اخیر</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>شیفت</th><th>افتتاح</th><th>انتظار نقد</th><th>شمارش</th><th>اختلاف</th><th>وضعیت / شرح</th></tr></thead><tbody>${data.history.map(r=>`<tr><td>${format(r.id)}</td><td>${fmtDate(r.opened_at)}</td><td>${money(r.expected_minor/100)}</td><td>${r.counted_minor===null?'—':money(r.counted_minor/100)}</td><td>${r.difference_minor===null?'—':money(r.difference_minor/100)}</td><td>${r.closed_at?'بسته':'باز'}<br>${esc(r.note)}</td></tr>`).join('')}</tbody></table></div></details></section>`}
function requestPanel(rows){return `<section class="panel mt"><h3>درخواست‌های هماهنگی و استرداد</h3><p class="dim">درخواست تا تأیید مدیر هیچ اثر مالی ندارد. شرایط پرداخت هنگام تأیید دوباره بررسی می‌شود.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>شناسه / عملیات</th><th>مبلغ / سفارش مرجع</th><th>مستند هماهنگی</th><th>دلیل</th><th>وضعیت / نتیجه</th><th>بررسی</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${format(r.id)} · ${esc(({payment:'پرداخت',refund:'استرداد',correction:'اصلاح روش'})[r.kind])}</td><td>${esc(r.order_code)}<br>${money(r.requested_amount_minor/100)} · ${r.requested_method==='cash'?'نقدی':'کارتخوان'}<br>${esc(r.requested_reference)}<br>${esc(r.operation_reason)}</td><td>${r.coordination==='ticket'?'تیکت':'حضوری'} · ${esc(r.reference)}</td><td>${esc(r.reason)}<br>درخواست‌کننده: ${esc(r.requester)}</td><td>${esc(({pending:'در انتظار',approved:'تأییدشده',rejected:'ردشده'})[r.status])}<br>${esc(r.resolution||'')} ${r.reviewer?'· '+esc(r.reviewer):''}</td><td>${model.user.role==='admin'&&r.status==='pending'?`<button class="btn btn-light btn-sm" data-action="review-financial" data-id="${r.id}" data-decision="approved">تأیید</button> <button class="btn btn-light btn-sm" data-action="review-financial" data-id="${r.id}" data-decision="rejected">رد</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">درخواستی وجود ندارد.</td></tr>'}</tbody></table></div></section>`}
function exceptionPanel(rows){if(model.user.role!=='admin')return '';return `<section class="panel mt"><h3>دفتر عملیات خارج از شیفت</h3><p class="dim">این مبالغ در افتتاحیه شیفت بعد دوباره منظور نمی‌شوند. نام هماهنگ‌کننده یا شماره تیکت، مستند داخلی است.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>عملیات</th><th>مستند</th><th>دلیل</th><th>زمان</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.kind)} #${format(r.target_id)}<br>${esc(r.actor)}</td><td>${esc(r.reference)}</td><td>${esc(r.reason)}</td><td>${fmtDate(r.created_at)}</td></tr>`).join('')||'<tr><td colspan="4">عملیات استثنایی ثبت نشده است.</td></tr>'}</tbody></table></div></section>`}
function coordinationInput(){let coordination=prompt('نوع هماهنگی: تیکت یا حضوری','تیکت');if(coordination===null)return null;coordination=({'تیکت':'ticket','حضوری':'in_person'})[coordination.trim()]||coordination.trim();const reference=prompt('شماره تیکت یا نام هماهنگ‌کننده (حداقل ۳ حرف)');if(reference===null)return null;const reason=prompt('دلیل هماهنگی (حداقل ۳ حرف)');if(reason===null)return null;return {coordination:coordination.trim(),reference,reason}}
async function cachedFinancialPost(path,body){
 const key=`cafeyar-operation-${model.user.id}-${path}`;let packet=null;
 try{packet=JSON.parse(sessionStorage.getItem(key)||'null')}catch{}
 if(packet&&JSON.stringify(packet.original)!==JSON.stringify(body))throw Error('نتیجه عملیات قبلی نامشخص است؛ ابتدا همان درخواست را تکرار و رسید آن را بررسی کنید');
 if(!packet){packet={original:body,body:{...body,idempotency_key:idKey()}};sessionStorage.setItem(key,JSON.stringify(packet))}
 try{const r=await post(path,packet.body);sessionStorage.removeItem(key);return r}catch(e){if(e.status&&e.status<500)sessionStorage.removeItem(key);throw e}
}
async function financialSubmit(kind,target,body){
 body.method=({'نقدی':'cash','کارتخوان':'pos'})[body.method.trim()]||body.method.trim();
 const states=await api('/cashier/shifts');
 let request=model.user.role!=='admin'&&kind!=='payment';let coordination=null;
 if(!states.active||request){
  if(model.user.role==='admin'&&!states.active){const mode=prompt('خارج از شیفت: ۱ ثبت مستقیم با هماهنگی مدیر؛ ۲ ارسال درخواست برای بررسی','۱');if(mode===null)return false;if(!['۱','1','direct','۲','2','request'].includes(mode.trim()))throw Error('گزینه ۱ یا ۲ را انتخاب کنید');request=!['۱','1','direct'].includes(mode.trim())}else request=true;
  coordination=coordinationInput();if(!coordination)return false;
 }
 let path=kind==='payment'?`/orders/${target}/pay`:`/payments/${target}/${kind==='refund'?'refunds':'correction'}`;
 let method=kind==='correction'?'PATCH':'POST';let payload={...body};
 if(kind==='refund')payload.idempotency_key=payload.idempotency_key||idKey();
 if(request){path='/cashier/requests';method='POST';payload={kind,target_id:target,payload,...coordination,idempotency_key:idKey()}}
 else if(coordination)payload.authorization=coordination;
 // Keep unresolved refund/request packets across a lost response; never issue a second refund blindly.
 const cacheKey=`cafeyar-financial-${model.user.id}-${kind}-${target}`;
 let old=null;try{old=JSON.parse(sessionStorage.getItem(cacheKey)||'null')}catch{}
 const cached=kind==='refund'||request;
 if(old){path=old.path;method=old.method;payload=old.payload}
 else if(cached)sessionStorage.setItem(cacheKey,JSON.stringify({path,method,payload}));
 try{await post(path,payload,method);if(cached||old)sessionStorage.removeItem(cacheKey)}catch(e){if(e.status&&e.status<500)sessionStorage.removeItem(cacheKey);throw e}
 toast(request?'درخواست برای بررسی مدیر ثبت شد':'عملیات ثبت شد');return true;
}

function productForm(data, cats){return `<form data-form="product" class="form-box"><h3>${data?'ویرایش محصول':'افزودن محصول جدید'}</h3><div class="field-grid three"><label>نام محصول<input name="name" required minlength="2" value="${esc(data?.name||'')}" placeholder="مثلاً موکا"></label><label>قیمت (تومان)<input name="price" type="number" min="0" required value="${data?.price??''}" placeholder="135000"></label><label>دسته‌بندی<select name="category_id">${cats.map(c=>`<option value="${c.id}" ${data?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><div class="field-grid"><label>توضیحات<input name="description" maxlength="300" value="${esc(data?.description||'')}"></label><label>آیکون محصول<input name="emoji" maxlength="12" value="${esc(data?.emoji||'☕')}"></label></div><label class="row mt"><input name="active" type="checkbox" ${!data||data.active?'checked':''}> نمایش در منوی مشتری</label><div class="row wrap mt"><button class="btn btn-primary" type="submit">${data?'ذخیره تغییرات':'افزودن محصول'}</button>${data?'<button class="btn btn-light" type="button" data-action="cancel-product">انصراف</button>':''}</div></form>`}
async function admin(){const c=await api('/admin/catalog');const current=c.products.find(p=>p.id===model.editingProduct);$('app').innerHTML=shell(`${heading('منو و مدیریت میزها','قیمت‌ها، دسته‌بندی‌ها و وضعیت نمایش محصولات از اینجا کنترل می‌شوند.')}<div class="grid cols-4 mb">${stat('کل محصولات',format(c.products.length),'محصول ثبت‌شده','▦')}${stat('محصول فعال',format(c.products.filter(p=>p.active).length),'قابل سفارش','✓',true)}${stat('دسته‌بندی',format(c.categories.length),'منوی ساخت‌یافته','◈')}${stat('میزهای فعال',format(c.tables.filter(t=>t.active).length),'QR اختصاصی','▣')}</div><section class="panel">${productForm(current,c.categories)}</section><section class="panel mt"><div class="panel-head"><h3>فهرست محصولات</h3>${mark(format(c.products.length)+' محصول')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>محصول</th><th>دسته‌بندی</th><th>قیمت</th><th>وضعیت</th><th>افزودنی</th><th>عملیات</th></tr></thead><tbody>${c.products.map(p=>`<tr><td><b>${esc(p.emoji)} ${esc(p.name)}</b><div class="dim" style="font-size:10px">${esc(p.description)}</div></td><td>${esc(c.categories.find(x=>x.id===p.category_id)?.name||'—')}</td><td class="money">${money(p.price)}</td><td>${mark(p.active?'فعال':'غیرفعال',p.active?'':'warning')}</td><td>${p.addons.map(a=>`${esc(a.name)} (${money(a.price)}) <button class="btn btn-outline btn-sm" data-action="addon-recipe" data-id="${a.id}">رسپی</button> <button class="btn btn-light btn-sm" data-action="delete-addon" data-id="${a.id}">×</button>`).join(' ، ')||'—'}<br><button class="btn btn-outline btn-sm" data-action="add-addon" data-id="${p.id}">+ افزودنی</button></td><td><button class="btn btn-light btn-sm" data-action="edit-product" data-id="${p.id}">ویرایش</button></td></tr>`).join('')}</tbody></table></div></section><div class="grid cols-2 mt"><section class="panel"><h3>دسته‌بندی جدید</h3><form data-form="category" class="row"><input name="name" required minlength="2" placeholder="نام دسته‌بندی"><button class="btn btn-primary">افزودن</button></form><div class="row wrap mt">${c.categories.map(x=>mark(x.name)).join('')}</div></section><section class="panel"><h3>QR میزها</h3><p class="dim" style="font-size:12px">QR به نشانی همین سرور اشاره می‌کند؛ برای گوشی‌های دیگر روی Wi-Fi باید آدرس شبکه محلی تنظیم شود.</p><a class="link" href="#qr-grid">مشاهده همه QRهای میزها ↓</a></section></div><section class="panel mt" id="qr-grid"><div class="panel-head"><h3>کد QR اختصاصی هر میز</h3><button class="btn btn-light btn-sm" data-action="print">چاپ این صفحه</button></div><div class="qr-grid">${c.tables.filter(t=>t.active).map(t=>`<div class="qr-tile"><img loading="lazy" src="/api/qr/${t.number}" alt="QR میز ${t.number}"><h4>میز ${format(t.number)}</h4><a href="/menu?table=${t.number}" target="_blank" class="link" style="font-size:11px">پیش‌نمایش منو</a></div>`).join('')}</div></section>`)}
async function inventory(){const all=await Promise.all([api('/inventory'),api('/admin/catalog')]);const data=all[0],catalog=all[1],ings=data.ingredients,products=catalog.products;const selected=model.selectedRecipe??products[0]?.id;model.selectedRecipe=selected;const parts=data.recipes.filter(r=>r.product_id===selected);$('app').innerHTML=shell(`${heading('انبار و بهای تمام‌شده','موجودی مواد اولیه، حد سفارش و دستور ساخت هر محصول در یک پایگاه داده.')}<div class="grid cols-3 mb">${stat('مواد اولیه',format(ings.length),'اقلام تعریف‌شده','◈')}${stat('موجودی کم',format(ings.filter(x=>x.stock<=x.reorder).length),'نیازمند بررسی','!',true)}${stat('ارزش موجودی',money(ings.reduce((s,i)=>s+i.stock*i.unit_cost,0)),'بر اساس آخرین قیمت واحد','▦')}</div><section class="panel"><div class="panel-head"><h3>موجودی لحظه‌ای</h3><span class="panel-sub">پس از تحویل سفارش، موجودی از دستور ساخت کسر می‌شود</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده اولیه</th><th>موجودی</th><th>نقطه سفارش</th><th>بهای واحد</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${ings.map(i=>`<tr><td><b>${esc(i.name)}</b></td><td>${format(i.stock)} ${esc(i.unit)}</td><td>${format(i.reorder)}</td><td class="money">${money(i.unit_cost)}</td><td>${i.stock<=i.reorder?mark('کمبود','danger'):mark('مناسب')}</td><td><div class="row gap-sm"><button class="btn btn-light btn-sm" data-action="restock" data-id="${i.id}" data-cost="${i.unit_cost}">خرید</button><button class="btn btn-outline btn-sm" data-action="edit-ingredient" data-id="${i.id}">ویرایش</button></div></td></tr>`).join('')}</tbody></table></div></section><div class="grid cols-2 mt"><section class="panel"><h3>افزودن ماده اولیه</h3><form data-form="ingredient" class="stack"><div class="field-grid"><label>نام<input name="name" required placeholder="مثلاً سیروپ وانیل"></label><label>واحد<input name="unit" required placeholder="میلی‌لیتر / گرم / عدد"></label><label>موجودی اولیه<input type="number" step="any" min="0" name="stock" required value="0"></label><label>قیمت هر واحد (تومان)<input type="number" step="any" min="0" name="unit_cost" required value="0"></label></div><label>نقطه سفارش<input type="number" step="any" min="0" name="reorder" required value="0"></label><button class="btn btn-primary">ثبت ماده اولیه</button></form></section><section class="panel"><h3>رسپی و بهای مواد هر محصول</h3><label>انتخاب محصول<select id="recipe-product">${products.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><form data-form="recipe" class="stack"><div class="grid cols-2">${ings.map(i=>{const q=parts.find(p=>p.ingredient_id===i.id)?.quantity||0;return `<label>${esc(i.name)} <small>(${esc(i.unit)})</small><input type="number" min="0" step="any" data-ingredient="${i.id}" value="${q}" placeholder="۰"></label>`}).join('')}</div><button class="btn btn-primary">ثبت دستور ساخت</button><small class="dim">اعداد صفر وارد رسپی نمی‌شوند. هر سفارش تکمیل‌شده مواد را از انبار کسر می‌کند.</small></form></section></div><section class="panel mt"><h3>گردش موجودی</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده</th><th>تغییر</th><th>علت</th><th>زمان</th></tr></thead><tbody>${data.moves.map(m=>`<tr><td>${esc(m.name)}</td><td>${format(m.delta)}</td><td>${m.reason==='sale'?'مصرف سفارش':m.reason==='restock'?'خرید':'اصلاح دستی'}</td><td>${fmtDate(m.created_at)}</td></tr>`).join('')||'<tr><td colspan="4">هنوز تراکنشی ثبت نشده است.</td></tr>'}</tbody></table></div></section>`)}
async function finance(){const d=await api('/finance'+reportQuery()),s=d.summary;let max=Math.max(1,...d.daily.map(x=>x.revenue));$('app').innerHTML=shell(`${heading('حسابداری و سود فروش','درآمد واقعی از تسویه‌های ثبت‌شده، هزینه کالا از رسپی و هزینه‌های عملیاتی جداگانه محاسبه می‌شود.')}${reportFilter()}<div class="grid cols-4 mb">${stat('فروش تحویل‌شده',money(s.revenue),'در تاریخ تکمیل، مستقل از پرداخت','◉',true)}${stat('بهای مواد مصرفی',money(s.cogs),'همه سفارش‌های تحویل‌شده','◈')}${stat('هزینه عملیاتی',money(s.operating_expenses),'بدون خرید موجودی','▣')}${stat('سود عملیاتی تخمینی',money(s.net_operating_profit),'درآمد − مواد مصرفی − هزینه عملیاتی','↗')}</div><section class="panel mb"><h3>وضعیت فعلی سفارش‌های ثبت‌شده در بازه</h3>${summaryRows([['تسویه‌نشده',format(d.order_states.payment.unpaid)],['تسویه‌شده بدون استرداد',format(d.order_states.payment.paid)],['استرداد جزئی',format(d.order_states.payment.partially_refunded)],['استرداد کامل',format(d.order_states.payment.refunded)],['تحویل‌شده',format(d.order_states.fulfillment.completed)]])}</section><section class="panel mb"><h3>فروش هفتگی (شروع شنبه)</h3>${bars(d.weekly.slice(-12).map(x=>({label:x.label,value:x.sales})))}</section><section class="panel mb"><h3>فروش روزانه خالص</h3>${bars(d.sales_daily.slice(-14).map(x=>({label:x.label,value:x.sales})))}</section><section class="panel mb"><h3>فروش ماهانه تحویل‌شده</h3>${bars(d.monthly.slice(-12).map(x=>({label:x.label,value:x.sales})))}</section><div class="grid cols-2"><section class="panel"><div class="panel-head"><h3>روند دریافتی روزانه</h3>${mark('۱۰ روز دارای دریافت')}</div>${bars(d.daily.slice().reverse().slice(-10).map(x=>({label:x.label,value:x.revenue})))}</section><section class="panel"><h3>خلاصه مالی</h3>${summaryRows([['فروش ناخالص تحویل‌شده',money(s.gross_sales)],['برگشت و کاهش فروش',money(s.sales_returns)],['فروش خالص',money(s.revenue)],['استرداد وجه',money(s.cash_refunded)],['هزینه ضایعات آماده‌سازی',money(s.waste_cost)],['دریافتی',money(s.cash_received)],['مطالبات فعلی سفارش‌های تحویل‌شده بازه',money(s.receivables)],['پیش‌دریافت سفارش‌های هنوز تحویل‌نشده',money(s.advances)],['بهای تمام‌شده سفارش‌ها',money(s.cogs)],['سود ناخالص',money(s.gross_profit)],['هزینه عملیاتی',money(s.operating_expenses)],['سود عملیاتی تخمینی',money(s.net_operating_profit)],['خرید مواد اولیه (جریان نقد)',money(s.inventory_purchases_cash_out)],['جریان نقدی تخمینی',money(s.cash_flow_estimate)]])}<p class="notice mt">خرید مواد اولیه به‌عنوان جریان نقد ثبت می‌شود و هم‌زمان با بهای مواد مصرفی از سود عملیاتی کم نمی‌شود؛ از دوباره‌شماری جلوگیری شده است.</p></section></div><div class="grid cols-2 mt"><section class="panel"><h3>ثبت هزینه جدید</h3><form class="stack" data-form="expense"><label>عنوان هزینه<input name="title" required placeholder="مثلاً هزینه آب و برق"></label><div class="field-grid"><label>مبلغ (تومان)<input name="amount" type="number" step="0.01" min="0.01" required></label><label>نوع هزینه<select name="kind"><option value="operating">هزینه عملیاتی</option><option value="purchase">خرید موجودی (نقدی)</option></select></label></div><label class="row"><input name="from_drawer" type="checkbox">پرداخت واقعی از وجه نقد صندوق</label><button class="btn btn-primary">ثبت هزینه</button></form></section><section class="panel"><h3>پرداخت بر حسب روش</h3>${d.methods.length?d.methods.map(x=>`<div class="row between" style="border-bottom:1px solid var(--line);padding:12px 0"><div>${x.method==='pos'?'کارتخوان':'نقدی'} <small class="dim">(${format(x.cnt)} تراکنش)</small></div><strong>${money(x.amount)}</strong></div>`).join(''):empty('تراکنشی وجود ندارد')}<p class="notice mt">این سیستم حسابداری مدیریتی دمو است، نه نرم‌افزار حسابداری رسمی مالیاتی یا سیستم صدور فاکتور قانونی.</p></section></div><section class="panel mt"><h3>آخرین هزینه‌ها</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>شرح</th><th>نوع</th><th>مبلغ</th><th>تاریخ</th></tr></thead><tbody>${d.expenses.map(x=>`<tr><td>${esc(x.title)}</td><td>${x.kind==='purchase'?'خرید انبار':'هزینه عملیاتی'}</td><td>${money(x.amount)}</td><td>${fmtDate(x.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`)}
function summaryRows(items){return items.map(([name,val],i)=>`<div class="row between" style="padding:11px 0;border-bottom:1px solid #e9eee5;${i===items.length-1?'font-weight:900;color:#376649':''}"><span>${esc(name)}</span><strong>${esc(val)}</strong></div>`).join('')}
function bars(points){const max=Math.max(1,...points.map(x=>Math.abs(x.value)));return `<div class="chart-bars">${points.length?points.map(x=>`<div class="bar-col" title="${esc(x.label)}: ${money(x.value)}"><strong style="font-size:9px">${format(Math.round(x.value/1000))}k</strong><b style="height:${Math.abs(x.value)/max*130}px;${x.value<0?'background:#a73c3c':''}"></b><span class="bar-label">${esc(x.label)}</span></div>`).join(''):empty('داده کافی برای نمودار وجود ندارد')}</div>`}
async function analytics(){const d=await api('/analytics'+reportQuery()),s=d.summary,max=Math.max(1,...d.top.map(x=>x.qty));$('app').innerHTML=shell(`${heading('داشبورد و تحلیل هوشمند','شاخص‌های فروش و پیشنهادهای قابل اقدام؛ نسخه فعلی بر مبنای قواعد شفاف، نه Grok API.')}${reportFilter()}<div class="grid cols-4 mb">${stat('کل سفارش‌ها',format(s.total_orders),'دوره داده‌های فعلی','▦')}${stat('فروش تحویل‌شده',money(s.revenue),'مستقل از دریافت وجه','◉',true)}${stat('مشتریان CRM',format(d.customer_count),'با رضایت ثبت اطلاعات','♡')}${stat('مشتریان تکراری',format(d.repeat_customers),'بر اساس سفارش‌های مرتبط','↺')}</div><div class="grid cols-2 mb">${stat('میانگین مبلغ سفارش',money(s.average_order_value),'سفارش‌های تحویل‌شده','◉')}${stat('سود ناخالص',money(s.gross_profit),'فروش تحویل‌شده منهای مواد مصرفی','↗')}</div><div class="grid cols-2"><section class="panel"><div class="panel-head"><h3>روند فروش</h3>${mark('۱۴ روز داده موجود')}</div>${bars(d.trend.map(x=>({label:new Intl.DateTimeFormat('fa-IR',{month:'numeric',day:'numeric',timeZone:'Asia/Tehran'}).format(new Date(x.day+'T12:00:00+03:30')),value:x.sales})))}</section><section class="panel"><h3>محصولات محبوب</h3>${d.top.map(x=>`<div class="progress-row"><strong>${esc(x.name)}</strong><div class="progress-track"><span style="width:${Math.max(3,x.qty/max*100)}%"></span></div><b>${format(x.qty)} عدد</b></div>`).join('')}</section></div><section class="panel mt"><div class="panel-head"><h3>موتور پیشنهاد مدیریتی</h3>${mark('تحلیل قاعده‌محور')}</div><div class="grid cols-2">${d.insights.map(x=>`<div class="insight">${esc(x)}</div>`).join('')}</div><p class="dim" style="font-size:11px;margin:16px 0 0">این خروجی از داده ثبت‌شده و قواعد ثابت تولید شده؛ پیش‌بینی مبتنی بر مدل یادگیری ماشین یا سرویس بیرونی هنوز متصل نیست.</p></section><section class="panel mt"><div class="panel-head"><h3>ساعت‌های پرتردد</h3><span class="panel-sub">بر اساس ساعت ثبت سفارش</span></div><div class="row wrap">${d.hours.map(x=>mark(x.hour+':۰۰ · '+format(x.orders)+' سفارش')).join('')}</div></section>`)}
async function crm(){const people=await api('/crm');$('app').innerHTML=shell(`${heading('باشگاه مشتریان (CRM)','داده مشتری فقط هنگام رضایت او برای باشگاه مشتریان ثبت می‌شود.')}<div class="grid cols-3 mb">${stat('مشتریان ثبت‌شده',format(people.length),'با شماره تماس و رضایت','♡',true)}${stat('مشتریان بازگشتی',format(people.filter(p=>p.visits>1).length),'بیش از یک سفارش','↺')}${stat('مجموع ارزش خرید مشتریان',money(people.reduce((a,p)=>a+p.spend,0)),'از پرداخت‌های مرتبط','◉')}</div><section class="panel"><div class="panel-head"><h3>فهرست مشتریان</h3>${mark('مشتریان دارای رضایت')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>مشتری</th><th>شماره</th><th>تعداد سفارش</th><th>ارزش خرید</th><th>آخرین سفارش</th><th>یادداشت</th><th></th></tr></thead><tbody>${people.map(p=>`<tr><td><b>${esc(p.name||'بدون نام')}</b></td><td dir="ltr">${esc(p.phone)}</td><td>${format(p.visits)}</td><td class="money">${money(p.spend)}</td><td>${fmtDate(p.last_order)}</td><td>${esc(p.notes||'—')}</td><td><button class="btn btn-light btn-sm" data-action="crm-note" data-id="${p.id}" data-note="${esc(p.notes||'')}">یادداشت</button></td></tr>`).join('')}</tbody></table></div></section><p class="notice mt">ارسال پیامک، کمپین‌های وفاداری و اتصال سرویس پیام‌رسان در نسخه دمو فعال نیستند. CRM فعلی شامل پرونده مشتری، تاریخچه سفارش و یادداشت مدیریتی است.</p>`)}
async function attendance(){const d=await api('/attendance');$('app').innerHTML=shell(`${heading('حضور و غیاب کارکنان','ثبت ورود و خروج در پنل؛ امکان اتصال ربات تلگرام با کد یک‌بارمصرف.')}<div class="grid cols-3 mb">${stat('کارکنان',format(d.users.length),'حساب‌های تعریف‌شده','♧')}${stat('رویدادهای تردد',format(d.punches.length),'آخرین ۸۰ ثبت','◷')}${stat('بات تلگرام',d.telegram_connected?'ربات آنلاین':'ربات آفلاین','وضعیت اتصال واقعی به تلگرام','✈')}</div><div class="grid cols-2"><section class="panel"><h3>ثبت تردد من</h3><p class="dim">واردشده با حساب ${esc(model.user.name)}</p><div class="row wrap"><button class="btn btn-primary" data-action="punch" data-type="in">◷ ثبت ورود</button><button class="btn btn-light" data-action="punch" data-type="out">↗ ثبت خروج</button></div><hr class="sep"><h3>اتصال به تلگرام</h3><p class="dim" style="font-size:12px">کد اتصال ۱۰ دقیقه معتبر است. در گفت‌وگوی ربات، دستور <code>/link CODE</code> را بفرستید، سپس <code>/in</code> یا <code>/out</code>.</p><button class="btn btn-outline" data-action="telegram-link">دریافت کد اتصال</button><div id="telegram-link-result" class="mt"></div>${!d.telegram_connected?'<p class="notice mt">ربات فعلاً آنلاین نیست. برای اتصال، برنامه راه‌انداز ربات را روی کامپیوتر سرور اجرا کنید.</p>':''}${d.telegram_connected&&d.telegram_username?`<p class="mt">ربات فعال: <a target="_blank" rel="noopener noreferrer" href="https://t.me/${esc(d.telegram_username)}">@${esc(d.telegram_username)}</a></p>`:''}</section><section class="panel"><h3>کاربران سیستم</h3>${d.users.map(u=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${esc(u.name)}</b><div class="dim" style="font-size:11px">${esc(u.username)} • ${esc(u.role)}</div></div>${mark(u.telegram_user_id?'تلگرام متصل':'پنل داخلی',u.telegram_user_id?'':'warning')}</div>`).join('')}</section></div><section class="panel mt"><h3>سوابق ورود و خروج</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>کارمند</th><th>رویداد</th><th>منبع</th><th>زمان</th></tr></thead><tbody>${d.punches.map(x=>`<tr><td>${esc(x.name)}</td><td>${mark(x.action==='in'?'ورود':'خروج',x.action==='in'?'':'warning')}</td><td>${x.source==='telegram'?'تلگرام':'پنل'}</td><td>${fmtDate(x.created_at)}</td></tr>`).join('')||'<tr><td colspan="4">هنوز ترددی ثبت نشده است.</td></tr>'}</tbody></table></div></section>`)}
function presentation(){if(!model.config?.demo){$('app').innerHTML=shell('<section class="panel"><h2>کافه یار ۳۶۰</h2><p>نسخه شبکه محلی؛ برای کار با بخش‌های مدیریتی وارد حساب خود شوید. داده نمونه و حساب‌های دمو در این حالت ایجاد نمی‌شوند.</p></section>');return}const steps=[['منوی مشتری','QR میز ۳ را باز کنید، اسپرسو یا لاته انتخاب و سفارش ثبت کنید.','/menu?table=3'],['پنل کارکنان','سفارش تازه وارد صف می‌شود و تا مرحله آماده/تحویل پیش می‌رود.','/staff'],['صندوق','سفارش را نقدی یا کارتخوان تسویه کنید. دوباره‌کاری مبلغ متوقف می‌شود.','/cashier'],['انبار و بهای تمام‌شده','با تکمیل سفارش، رسپی مصرف می‌شود؛ خرید و گردش موجودی ثبت می‌گردد.','/inventory'],['حسابداری و داشبورد','دریافتی، هزینه، سود عملیاتی، روند فروش و پرفروش‌ها قابل مشاهده‌اند.','/analytics'],['CRM و حضور و غیاب','پرونده مشتری رضایتمند و ثبت تردد کارکنان را نمایش دهید.','/crm']];$('app').innerHTML=shell(`<section class="presentation-hero"><p class="eyebrow" style="color:#d4eab8">THE ALL-IN-ONE CAFE PLATFORM</p><h1>از اولین اسکن QR تا آخرین گزارش فروش؛ همه چیز در یک جریان.</h1><p>دموی قابل اجرا برای ارائه به صاحب کافه: سفارش مشتری، بار، صندوق، انبار، حسابداری، باشگاه مشتریان و تحلیل فروش همگی از یک دیتابیس استفاده می‌کنند.</p><div class="row wrap"><a class="btn btn-accent" href="/menu?table=3">شروع سناریوی زنده ↖</a><a class="btn btn-white" href="/analytics">داشبورد مدیریت</a></div></section><div class="info-cards mt"><div class="info-card"><b>۱</b><p>دیتابیس مشترک برای تمام پنل‌ها</p></div><div class="info-card"><b>۱۲</b><p>میز نمونه با QR اختصاصی</p></div><div class="info-card"><b>۳</b><p>نقش مدیر، باریستا، صندوق‌دار</p></div><div class="info-card"><b>۰</b><p>درگاه پرداخت آنلاین متصل (به درخواست شما)</p></div></div>${heading('سناریوی شش‌مرحله‌ای فروش','هر مرحله به یک صفحه عملیاتی و اطلاعات واقعی همین دمو متصل است.','')}<div class="grid cols-3">${steps.map((s,i)=>`<article class="demo-step"><div class="step-number">${format(i+1)}</div><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p><a class="btn btn-outline btn-sm" href="${s[2]}">نمایش قابلیت ↗</a></article>`).join('')}</div><section class="panel mt"><h3>اطلاعات ورود برای نمایش دمو</h3>${summaryRows([['مدیر','admin'],['صندوق‌دار','cashier'],['باریستا','barista']])}<p class="notice mt">رمز ثابت نمایشی وجود ندارد. رمز هر حساب را هنگام راه‌اندازی محلی تعیین کنید؛ برای حساب موجود از ابزار تغییر رمز استفاده کنید. HTTPS و نسخه پشتیبان برای استفاده عملیاتی بررسی شوند.</p></section><section class="panel mt"><h3>آنچه در این نسخه واقعاً انجام می‌شود</h3><p>ثبت سفارش و تسویه در دیتابیس مشترک، گردش وضعیت، کاهش خودکار موجودی پس از تکمیل، حساب درآمد و هزینه، گزارش تحلیلی قاعده‌محور، مدیریت منو و QR میزها، ثبت CRM با رضایت و ثبت تردد پنلی. اتصال تلگرام تنها پس از تنظیم توکن و اجرای سرویس فعال خواهد شد. درگاه آنلاین متصل نیست.</p></section>`)}


function reportQuery(){const p=new URLSearchParams();if(model.reportStart)p.set('start',model.reportStart);if(model.reportEnd)p.set('end',model.reportEnd);return p.size?'?'+p.toString():''}
function reportFilter(){return `<form data-form="report-period" class="row wrap mb"><label>از تاریخ میلادی<input type="date" name="start" value="${esc(model.reportStart||'')}"></label><label>تا تاریخ میلادی<input type="date" name="end" value="${esc(model.reportEnd||'')}"></label><button class="btn btn-outline" type="submit">اعمال بازه</button><span class="dim">فروش در تاریخ تحویل؛ دریافتی در تاریخ پرداخت. روزها، هفته‌های شنبه و ماه‌ها شمسی و مطابق ساعت تهران هستند.</span></form>`}
function discrepancyPanel(rows){return `<section class="panel mt"><h3>گزارش مغایرت صندوق</h3><p class="dim">ثبت یا بستن گزارش به‌تنهایی مبلغ پرداخت و موجودی را تغییر نمی‌دهد.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>سفارش</th><th>انتظار</th><th>مشاهده‌شده</th><th>اختلاف</th><th>شرح</th><th>ثبت‌کننده</th><th>وضعیت</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.code)}</td><td>${money(r.expected_amount)}</td><td>${money(r.reported_amount)}</td><td>${money(r.reported_amount-r.expected_amount)}</td><td>${esc(r.reason)}${r.resolution?`<br>نتیجه: ${esc(r.resolution)}`:''}</td><td>${esc(r.actor)}</td><td>${esc(r.status==='open'?'باز':'بررسی‌شده')}${r.status==='open'&&model.user.role==='admin'?` <button class="btn btn-light btn-sm" data-action="resolve-discrepancy" data-id="${r.id}">ثبت نتیجه</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7">مغایرتی گزارش نشده است.</td></tr>'}</tbody></table></div></section>`}
async function cashierAction(action,b){
 if(action==='cash-page'){model.cashOffset=Number(b.dataset.offset);await cashier();return true}
 if(action==='review-financial'){
  const resolution=prompt('نتیجه و دلیل بررسی مدیر (حداقل ۳ حرف)');if(resolution===null)return true;
  await post(`/cashier/requests/${b.dataset.id}/review`,{decision:b.dataset.decision,resolution},'PATCH');await cashier();toast('نتیجه بررسی ثبت شد');return true;
 }
 if(action==='refund-payment'){
  const receipt=await api(`/orders/${b.dataset.oid}/receipt`);
  const amount=prompt(`مبلغ استرداد (تومان)، حداکثر ${receipt.remaining_refundable_minor/100}`,String(receipt.remaining_refundable_minor/100));if(amount===null)return true;
  const method=prompt('روش واقعی برگشت وجه: نقدی یا کارتخوان',receipt.payment.method==='cash'?'نقدی':'کارتخوان');if(method===null)return true;
  const reason=prompt('دلیل استرداد (حداقل ۳ حرف)');if(reason===null)return true;
  const reference=prompt('شماره پیگیری برگشت وجه (اختیاری)','');if(reference===null)return true;
  if(!confirm('استرداد کامل پیش از تحویل، سفارش را لغو می‌کند. مواد آماده‌شده ضایعات محسوب می‌شوند. ثبت شود؟'))return true;
  if(await financialSubmit('refund',receipt.payment.id,{amount,method:method.trim(),reason,reference,expected_revision:receipt.payment.revision}))await cashier();return true;
 }

 if(action==='payment-correction'){
  const r=await api(`/orders/${b.dataset.oid}/receipt`);const method=prompt('روش درست: نقدی یا کارتخوان',r.payment.method==='cash'?'نقدی':'کارتخوان');if(method===null)return true;
  const reference=prompt('شماره پیگیری درست',r.payment.reference);if(reference===null)return true;const reason=prompt('دلیل اصلاح روش پرداخت (حداقل ۳ حرف)');if(reason===null)return true;
  if(await financialSubmit('correction',r.payment.id,{method:method.trim(),reference,reason,expected_revision:r.payment.revision}))await cashier();return true;
 }
 if(action==='payment-discrepancy'){
  const amount=prompt('مبلغ واقعی مشاهده‌شده (تومان؛ ارقام انگلیسی)');if(amount===null||amount.trim()==='')return true;const reason=prompt('شرح مغایرت (حداقل ۳ حرف)');if(reason===null)return true;
  await post(`/payments/${b.dataset.pid}/discrepancies`,{reported_amount:Number(amount),reason,idempotency_key:idKey()});await cashier();toast('گزارش مغایرت ثبت شد');return true;
 }
 if(action==='resolve-discrepancy'){
  const resolution=prompt('نتیجه بررسی؛ این عملیات به‌تنهایی وجهی جابه‌جا نمی‌کند');if(resolution===null)return true;
  await post(`/cashier/discrepancies/${b.dataset.id}/resolve`,{resolution},'PATCH');await cashier();toast('نتیجه بررسی ثبت شد');return true;
 }
 return false;
}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{if(await cashierAction(action,b))return;switch(action){case 'login':openLogin();break;case 'logout':await post('/auth/logout',{});model.user=null;toast('از حساب خارج شدید');await boot();break;case 'category':model.category=b.dataset.id;await customer();$('menu-list')?.scrollIntoView({behavior:'smooth'});break;case 'add':{const id=Number(b.dataset.id);const item=model.cart.find(x=>x.product_id===id&&!x.addon_id);if(item)item.qty++;else model.cart.push({product_id:id,qty:1,addon_id:null,key:idKey()});syncCart();toast('به سبد سفارش افزوده شد');break}case 'qty':{const item=model.cart[Number(b.dataset.index)];if(item){item.qty+=Number(b.dataset.delta);if(item.qty<=0)model.cart.splice(Number(b.dataset.index),1)}syncCart();break}case 'open-cart':$('cart-pane').classList.add('open');break;case 'close-cart':$('cart-pane').classList.remove('open');break;case 'refresh':await boot();toast('اطلاعات به‌روزرسانی شد');break;case 'status':{const status=b.dataset.status,aid=Number(b.dataset.id);let allergy_ack=false;if(status==='accepted'&&b.closest('.order-card')?.querySelector('.allergy')){allergy_ack=confirm('سفارش حساسیت غذایی دارد. آیا هشدار را مطالعه کرده‌اید و به مسئول آماده‌سازی اطلاع داده‌اید؟');if(!allergy_ack)return}if(status==='cancelled'&&!confirm('سفارش لغو شود؟'))return;await post(`/orders/${aid}/status`,{status,allergy_ack},'PATCH');await boot();toast('وضعیت سفارش به‌روزرسانی شد');break}case 'pay':{const method=prompt('روش پرداخت: نقدی یا کارتخوان',b.dataset.method==='cash'?'نقدی':'کارتخوان');if(!method)return;const reference=prompt('شماره پیگیری/رسید (اختیاری)','')||'';if(!confirm('تسویه این سفارش ثبت شود؟'))return;if(await financialSubmit('payment',Number(b.dataset.id),{method:method.trim(),reference}))await boot();break}case 'edit-product':model.editingProduct=Number(b.dataset.id);await admin();window.scrollTo({top:0,behavior:'smooth'});break;case 'cancel-product':model.editingProduct=null;await admin();break;case 'add-addon':{const name=prompt('نام افزودنی جدید، مثلاً شات اضافه');if(!name)return;const p=prompt('قیمت افزودنی به تومان','30000');if(!p)return;await post(`/admin/products/${b.dataset.id}/addons`,{name,price:Number(p)});await admin();toast('افزودنی ثبت شد');break}case 'addon-recipe':{const aid=Number(b.dataset.id);const [items,inventoryData]=await Promise.all([api(`/admin/addons/${aid}/recipe`),api('/inventory')]);$('addon-recipe-dialog').dataset.aid=String(aid);$('addon-recipe-fields').innerHTML=inventoryData.ingredients.map(i=>{const delta=items.find(x=>x.ingredient_id===i.id)?.delta||0;return `<label>${esc(i.name)} <small>(${esc(i.unit)})</small><input type="number" step="any" data-ingredient="${i.id}" value="${delta}"></label>`}).join('');$('addon-recipe-dialog').showModal();break}case 'close-addon-recipe':$('addon-recipe-dialog').close();break;case 'delete-addon':if(confirm('افزودنی حذف شود؟')){await api('/admin/addons/'+b.dataset.id,{method:'DELETE'});await admin();toast('حذف شد')}break;case 'restock':{const quantity=prompt('چه مقدار به موجودی اضافه شود؟','100');if(!quantity)return;const price=prompt('قیمت خرید هر واحد (تومان)',b.dataset.cost||'0');if(price===null)return;await cachedFinancialPost(`/inventory/${b.dataset.id}/restock`,{quantity:Number(quantity),unit_cost:Number(price)});await inventory();toast('خرید و افزایش موجودی ثبت شد');break}case 'edit-ingredient':{const d=await api('/inventory');const item=d.ingredients.find(x=>x.id===Number(b.dataset.id));if(!item)return;const fields={};for(const [key,desc] of [['name','نام'],['unit','واحد'],['stock','موجودی'],['unit_cost','بهای هر واحد'],['reorder','حد سفارش']]){const v=prompt(desc,String(item[key]));if(v===null)return;fields[key]=['name','unit'].includes(key)?v:Number(v)}await post(`/inventory/ingredients/${item.id}`,fields,'PUT');await inventory();toast('ماده اولیه ویرایش شد');break}case 'crm-note':{const n=prompt('یادداشت مرتبط با مشتری',b.dataset.note||'');if(n===null)return;await post(`/crm/${b.dataset.id}`,{notes:n},'PATCH');await crm();toast('یادداشت ذخیره شد');break}case 'punch':await post('/attendance/punch',{action:b.dataset.type});await attendance();toast('تردد ثبت شد');break;case 'telegram-link':{const r=await post('/attendance/telegram-link',{});$('telegram-link-result').innerHTML=`<div class="notice green">دستور اتصال: <strong dir="ltr">${esc(r.instruction)}</strong><br>مدت اعتبار: ۱۰ دقیقه</div>`;break}case 'print':window.print();break}
}catch(err){toast(err.message,true)}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.action==='addon'){const item=model.cart[Number(el.dataset.index)];if(item){const aid=Number(el.value)||null;const similar=model.cart.find(x=>x!==item&&x.product_id===item.product_id&&x.addon_id===aid);if(similar){similar.qty+=item.qty;model.cart=model.cart.filter(x=>x!==item)}else item.addon_id=aid;syncCart()}}if(el.id==='recipe-product'){model.selectedRecipe=Number(el.value);inventory()}});
document.addEventListener('submit',async e=>{const form=e.target,kind=form.dataset.form;if(!kind)return;e.preventDefault();const f=new FormData(form);const value=k=>String(f.get(k)||'').trim();try{if(kind==='cashier-filter'){model.cashFilter=value('payment_status');model.cashOffset=0;await cashier();return}if(kind==='open-shift'){await post('/cashier/shifts',{opening_amount:value('opening_amount'),idempotency_key:idKey()});await cashier();return}if(kind==='close-shift'){await post(`/cashier/shifts/${form.dataset.id}/close`,{counted_amount:value('counted_amount'),note:value('note')});await cashier();return}if(kind==='report-period'){const start=value('start'),end=value('end');if(start&&end&&start>end)throw Error('شروع بازه باید قبل از پایان باشد');model.reportStart=start;model.reportEnd=end;await boot();return}if(kind==='addon-recipe'){const aid=Number($('addon-recipe-dialog').dataset.aid);const parts=Array.from(form.querySelectorAll('[data-ingredient]')).map(x=>({ingredient_id:Number(x.dataset.ingredient),delta:Number(x.value)||0})).filter(p=>p.delta!==0);await post(`/admin/addons/${aid}/recipe`,{parts},'PUT');$('addon-recipe-dialog').close();await admin();toast('رسپی افزودنی ذخیره شد');return}if(kind==='order'){if(!model.cart.length)return toast('سبد خرید خالی است',true);const fulfillment=value('fulfillment'),table=getTable();let phone=value('phone').replace(/[۰-۹]/g,ch=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(ch))).replace(/[٠-٩]/g,ch=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(ch)));const body={items:model.cart.map(x=>({product_id:x.product_id,qty:x.qty,addon_id:x.addon_id})),fulfillment,table:fulfillment==='table'?table:null,customer_name:value('name'),phone,consent:!!f.get('consent'),note:value('note'),allergy_note:value('allergy'),payment_method:value('payment'),idempotency_key:model.pendingKey};const result=await post('/orders',body);model.order={...result};try{sessionStorage.setItem('cafe-nima-order',JSON.stringify(model.order))}catch{}model.pendingKey=idKey();model.cart=[];syncCart();$('cart-pane').classList.remove('open');$('order-result').innerHTML=orderStatusHtml();$('order-result').scrollIntoView({behavior:'smooth'});toast('سفارش به سرور و صف کارکنان ارسال شد');return}if(kind==='product'){const body={name:value('name'),description:value('description'),price:Number(value('price')),emoji:value('emoji'),category_id:Number(value('category_id')),active:!!f.get('active')};if(model.editingProduct)await post(`/admin/products/${model.editingProduct}`,body,'PUT');else await post('/admin/products',body);model.editingProduct=null;await admin();toast('محصول ذخیره شد');return}if(kind==='category'){await post('/admin/categories',{name:value('name')});await admin();toast('دسته‌بندی اضافه شد');return}if(kind==='ingredient'){await post('/inventory/ingredients',{name:value('name'),unit:value('unit'),stock:Number(value('stock')),unit_cost:Number(value('unit_cost')),reorder:Number(value('reorder'))});await inventory();toast('ماده اولیه ثبت شد');return}if(kind==='recipe'){let parts=Array.from(form.querySelectorAll('[data-ingredient]')).filter(x=>Number(x.value)>0).map(x=>({ingredient_id:Number(x.dataset.ingredient),quantity:Number(x.value)}));await post(`/inventory/recipes/${model.selectedRecipe}`,{parts},'PUT');await inventory();toast('دستور ساخت ذخیره شد');return}if(kind==='expense'){const body={title:value('title'),amount:value('amount'),kind:value('kind'),from_drawer:!!f.get('from_drawer')};if(body.from_drawer&&!(await api('/cashier/shifts')).active){const authorization=coordinationInput();if(!authorization)return;body.authorization=authorization}await cachedFinancialPost('/finance/expenses',body);await finance();toast('هزینه ثبت شد');return}}catch(err){toast(err.message,true)}});
setInterval(()=>{if(['staff','cashier'].includes(ROUTE)&&document.visibilityState==='visible'&&!document.querySelector('dialog[open]'))boot()},12000);
boot();
